-- Invitations of e-mail accounts (staff, HR, clinics, assistance): a single-use link to set the first password, sent by the API worker through the SMTP of MIG; the TOTP factor is set up at the first sign-in.
-- Generated by scripts/gen-schema.mjs from packages/domain/src/store/sql/migrationsInvitations.ts. Do not edit by hand:
-- change the TypeScript source and run `node scripts/gen-schema.mjs`.

-- One row per invitation; a new one of the same account revokes the open one. Only the SHA-256 of the token is kept
-- for the lookup; the token itself is sealed with the PII key (token_enc, token_key_ver) until the e-mail leaves and
-- dropped then. A send is leased for two minutes (two workers never send one twice) and tried at most 10 times.
create table app.invitations (
  id uuid primary key,
  user_id uuid not null,
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  token_enc bytea,
  token_key_ver smallint,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  sent_at timestamptz,
  used_at timestamptz,
  revoked_at timestamptz,
  attempts integer not null default 0 check (attempts >= 0),
  lease_until timestamptz,
  check (expires_at > created_at),
  check ((token_enc is null) = (token_key_ver is null))
);
create index invitations_user_idx on app.invitations (user_id, created_at desc);
create index invitations_unsent_idx on app.invitations (created_at) where sent_at is null and used_at is null and revoked_at is null;
comment on table app.invitations is 'Single-use links to set the first password of an e-mail account (repo invitations). System only: the API.';
alter table app.invitations enable row level security;
revoke all on app.invitations from public, anon, authenticated;
grant select, insert, update, delete on app.invitations to service_role;

-- Expired sessions, challenges, attempt counters and tokens (epoch columns are milliseconds).
create or replace function app.job_cleanup_expired() returns jsonb
  language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_now bigint := (extract(epoch from now()) * 1000)::bigint;
  v_day bigint := 24 * 3600 * 1000;
  v jsonb := '{}'::jsonb;
  n bigint;
begin
  delete from public.sessions where last_activity < v_now - 12 * 3600 * 1000; get diagnostics n = row_count; v := v || jsonb_build_object('sessions', n);
  delete from public.challenges where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('challenges', n);
  delete from public.grants where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('grants', n);
  delete from public.lockouts where until < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('lockouts', n);
  delete from public.login_failures where "at" < v_now - v_day; get diagnostics n = row_count; v := v || jsonb_build_object('login_failures', n);
  delete from public.check_attempts where "at" < v_now - v_day; get diagnostics n = row_count; v := v || jsonb_build_object('check_attempts', n);
  delete from public.check_locks where until < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('check_locks', n);
  delete from public.card_tokens where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('card_tokens', n);
  delete from public.access_tokens where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('access_tokens', n);
  delete from public.idempotency where "at" < v_now - v_day; get diagnostics n = row_count; v := v || jsonb_build_object('idempotency', n);
  delete from public.api_calls where "at" < v_now - 3600 * 1000; get diagnostics n = row_count; v := v || jsonb_build_object('api_calls', n);
  delete from public.sessions s using public.app_sessions a where a.session_id = s.id and a.last_activity < now() - interval '31 minutes'; get diagnostics n = row_count; v := v || jsonb_build_object('app_sessions', n);
  delete from public.app_auth_challenges where expires_at < now(); get diagnostics n = row_count; v := v || jsonb_build_object('app_auth_challenges', n);
  delete from app.job_queue where done_at < now() - interval '7 days'; get diagnostics n = row_count; v := v || jsonb_build_object('job_queue', n);
  delete from app.test_phone_codes where "at" < now() - interval '5 minutes'; get diagnostics n = row_count; v := v || jsonb_build_object('test_phone_codes', n);
  delete from app.job_marks where "at" < now() - interval '400 days'; get diagnostics n = row_count; v := v || jsonb_build_object('job_marks', n);
  delete from app.invitations where coalesce(used_at, revoked_at, expires_at) < now() - interval '90 days'; get diagnostics n = row_count; v := v || jsonb_build_object('invitations', n);
  return v;
end $$;

revoke execute on function app.job_cleanup_expired() from public, authenticated;

