alidated', 'migration_submitted', 'migration_applied', 'migration_rejected', 'migration_rolled_back', 'migration_scan_attached', 'family_consent_granted', 'family_consent_revoked', 'family_request_created', 'family_request_decided', 'payout_card_changed', 'task_created', 'task_done', 'task_taken', 'task_rejected', 'task_reminded', 'invitation_sent', 'invitation_accepted'));
